/**
 * Differential harness: runs the reference executable and the Node port with
 * byte-identical argv, and compares stdout / stderr / exit code exactly.
 *
 * argv bytes are delivered through bash $'...' quoting so that arbitrary
 * (including invalid-UTF-8) bytes reach execve untouched. NUL is not
 * representable in argv at all, so it is rejected up front.
 */
import { spawnSync } from 'node:child_process';

const PY = '/workspace/dataset/test7_executable';
const JS = '/output/test7.mjs';

/** Quote a Buffer as a bash $'...' literal, escaping every byte explicitly. */
function bashQuote(buf) {
  let out = "$'";
  for (const b of buf) {
    if (b === 0) throw new Error('NUL cannot appear in argv');
    out += '\\x' + b.toString(16).padStart(2, '0');
  }
  return out + "'";
}

export function toBuf(v) {
  return Buffer.isBuffer(v) ? v : Buffer.from(String(v), 'utf8');
}

/** Run one argv vector (array of strings/Buffers) against both programs. */
export function runCase(argv, env = {}) {
  const quoted = argv.map((a) => bashQuote(toBuf(a))).join(' ');
  const envPrefix = Object.entries(env)
    .map(([k, v]) => `${k}=${bashQuote(toBuf(v))}`)
    .join(' ');
  const prefix = envPrefix ? envPrefix + ' ' : '';

  const run = (cmd) =>
    spawnSync('/bin/bash', ['-c', `${prefix}${cmd} ${quoted}`], { maxBuffer: 1 << 26 });

  const py = run(PY);
  const js = run(`node ${JS}`);
  return {
    py: { out: py.stdout, err: py.stderr, code: py.status },
    js: { out: js.stdout, err: js.stderr, code: js.status },
  };
}

/**
 * Compare one case. stdout and exit code must match byte for byte. stderr is
 * compared after masking PyInstaller's `[PYI-<pid>:ERROR]` line, whose pid can
 * never match across two different processes.
 */
export function checkCase(argv, env = {}) {
  const { py, js } = runCase(argv, env);
  const problems = [];
  if (!py.out.equals(js.out)) {
    problems.push(`stdout differs\n  py: ${py.out.toString('latin1')}\n  js: ${js.out.toString('latin1')}`);
  }
  if (py.code !== js.code) problems.push(`exit code differs: py=${py.code} js=${js.code}`);

  const mask = (b) => b.toString('utf8').replace(/\[PYI-\d+:ERROR\]/g, '[PYI:ERROR]');
  if (mask(py.err) !== mask(js.err)) {
    problems.push(`stderr differs\n  py: ${mask(py.err)}\n  js: ${mask(js.err)}`);
  }
  return problems;
}

/** Run a list of cases, print failures, return the failure count. */
export function runSuite(name, cases) {
  let failed = 0;
  for (const entry of cases) {
    const argv = Array.isArray(entry) ? entry : entry.argv;
    const env = Array.isArray(entry) ? {} : entry.env || {};
    const label = Array.isArray(entry)
      ? argv.map((a) => toBuf(a).toString('latin1')).join(' | ')
      : entry.label || '';
    const problems = checkCase(argv, env);
    if (problems.length > 0) {
      failed += 1;
      process.stdout.write(`FAIL [${name}] ${label}\n`);
      for (const p of problems) process.stdout.write('  ' + p.replace(/\n/g, '\n  ') + '\n');
    }
  }
  process.stdout.write(`[${name}] ${cases.length - failed}/${cases.length} passed\n`);
  return failed;
}
=====SMOKE
import { runSuite } from './harness.mjs';
const cases = [
  ['--a','x','--b','y'],
  ['--a', Buffer.from([0x62,0x61,0x64,0x80,0x62]), '--b','x'],   // invalid UTF-8
  ['--a', Buffer.from([0xff,0xfe]), '--b','x'],
  ['--a','1','--b','2','--'],
  ['--a','1','--','--b','2'],
  ['--help'],
  ['--a','1'],
  [],
  ['--a','1','--b','2','--c','3'],
  ['--a', Buffer.from([0xf0,0x9f,0x98,0x80]), '--b', Buffer.from([0xef,0xbf,0xbd])],
];
process.exit(runSuite('smoke', cases) ? 1 : 0);
=====EDGES
import { runSuite } from './harness.mjs';
const cases = [
  ['-h=x'], ['--help=x'], ['--a','1','--b','2','-h=x'],
  ['--a=1','--b=2'], ['--a==1','--b','2'], ['--a=','--b='],
  ['--hel'], ['--aa','1','--b','2'], ['-hx'],
  ['--a','-','--b','2'], ['--a','-5','--b','-.5'], ['--a','-0.0','--b','-1.'],
  ['--a','1','--b','2','--','--','--'], ['--','--a','1','--b','2'],
  ['--a','1','--b','2','--a'], ['--a','1','--a','9','--b','2'],
  ['--b','2','--a','1'], ['--a','+5','--b','--5'],
  ['--a','x'], ['--b','x'], [], ['--a','1','--b','2','extra'],
  ['--a','1','--b','2','-h'], ['-h','--a'],
];
process.exit(runSuite('edges', cases) ? 1 : 0);
=====SAMPLES
import { runCase } from './harness.mjs';
// The four sample cases documented in test7.py, with their expected output.
const samples = [
  ['carriage\rreturn', '456',        `b'["carriage\\\\rreturn","456"]'\nb'["456","carriage\\\\rreturn"]'\n`],
  [' whitespace ', 'encoding',       `b'[" whitespace ","encoding"]'\nb'[" whitespace ","encoding"]'\n`],
  ['empty_string', 'canonical',      `b'["empty_string","canonical"]'\nb'["canonical","empty_string"]'\n`],
  ['\t\ttabs\t\t', 'python',         `b'["\\\\t\\\\ttabs\\\\t\\\\t","python"]'\nb'["\\\\t\\\\ttabs\\\\t\\\\t","python"]'\n`],
];
let bad = 0;
for (const [a, b, expected] of samples) {
  const { py, js } = runCase(['--a', a, '--b', b]);
  const jsOut = js.out.toString('latin1');
  const pyOut = py.out.toString('latin1');
  const okDoc = jsOut === expected;
  const okRef = jsOut === pyOut;
  if (!okDoc || !okRef) { bad++; console.log(`FAIL doc=${okDoc} ref=${okRef}\n  exp: ${JSON.stringify(expected)}\n  js : ${JSON.stringify(jsOut)}`); }
  else console.log(`OK  matches documented output AND reference: ${JSON.stringify(a)} ${JSON.stringify(b)}`);
}
console.log(bad ? `${bad} FAILED` : 'all 4 documented samples reproduced verbatim');

#!/usr/bin/env node
/**
 * test7.mjs — Node.js port of /workspace/dataset/test7.py
 *
 * Original:
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--a', type=str, required=True)
 *     parser.add_argument('--b', type=str, required=True)
 *     args = parser.parse_args()
 *
 *     data = [args.a, args.b]
 *     result1 = canonicaljson.encode_canonical_json(data)
 *     result2 = canonicaljson.encode_canonical_json(sorted(data))
 *     print(result1)
 *     print(result2)
 *
 * `print()` of a `bytes` object emits its repr, so both lines come out as
 * `b'...'` with Python's byte-escaping rules applied on top of the JSON text.
 */

import { ArgumentParser } from './lib/argparse.mjs';
import { encodeCanonicalJson } from './lib/canonicaljson.mjs';
import { pySorted } from './lib/pysort.mjs';
import { scriptArgs } from './lib/pyargv.mjs';
import { pyPrint } from './lib/pyio.mjs';
import { runMain } from './lib/pyruntime.mjs';

export function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: 'str', required: true });
  parser.addArgument('--b', { type: 'str', required: true });
  const args = parser.parseArgs(scriptArgs());

  const data = [args.a, args.b];
  const result1 = encodeCanonicalJson(data); // Encode list as canonical JSON
  const result2 = encodeCanonicalJson(pySorted(data)); // Encode sorted list as canonical JSON
  pyPrint(result1);
  pyPrint(result2);
}

// Frame list for the one unhandled exception this program can raise: a lone
// surrogate in either argument makes the UTF-8 encode inside
// encode_canonical_json fail, which CPython reports from test7.py line 12.
runMain(main, {
  script: 'test7',
  traceback: [
    { file: 'test7.py', line: 18, name: '<module>' },
    { file: 'test7.py', line: 12, name: 'main' },
    { file: 'canonicaljson/__init__.py', line: 85, name: 'encode_canonical_json' },
  ],
});

/**
 * pysort.mjs — `sorted()` over Python strings.
 *
 * `str.__lt__` compares code points. JS's `<` compares UTF-16 code units, and
 * the two disagree for every astral character: U+1F600 encodes as D83D DE00, so
 * JS ranks it *below* U+E000..U+FFFF while Python ranks it above. The reference
 * executable confirms Python's order:
 *
 *   --a $'\xf0\x9f\x98\x80' --b $'\xef\xbf\xbd'
 *     -> b'["\xef\xbf\xbd","\xf0\x9f\x98\x80"]'   (U+FFFD sorts first)
 *
 * so the comparison below walks code points explicitly.
 */

/** `(a > b) - (a < b)` for Python `str`, comparing code point by code point. */
export function compareCodePoints(a, b) {
  const ia = a[Symbol.iterator]();
  const ib = b[Symbol.iterator]();

  for (;;) {
    const na = ia.next();
    const nb = ib.next();
    if (na.done) return nb.done ? 0 : -1; // a is a proper prefix of b
    if (nb.done) return 1;
    const ca = na.value.codePointAt(0);
    const cb = nb.value.codePointAt(0);
    if (ca !== cb) return ca < cb ? -1 : 1;
  }
}

/**
 * `sorted(iterable)` for a sequence of strings.
 *
 * Returns a new array; the input is left untouched, matching `sorted()` rather
 * than `list.sort()`. `Array.prototype.sort` is stable in every supported V8,
 * which lines up with Python's Timsort for equal elements.
 */
export function pySorted(items) {
  return Array.from(items).sort(compareCodePoints);
}
=====CANONICALJSON
/**
 * canonicaljson.mjs — reimplementation of the `canonicaljson` package's public
 * surface, derived from the reference executable's observable behaviour.
 *
 * `encode_canonical_json(obj)` produces `bytes`:
 *
 *   * keys sorted, no insignificant whitespace (`separators=(',', ':')`)
 *   * `ensure_ascii=False`, so non-ASCII text is carried as raw UTF-8 rather
 *     than `\uXXXX` escapes — this is why the reference prints
 *     b'["\xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e","ascii"]' for Japanese input
 *   * the JSON *text* is built first and encoded to UTF-8 last, so a lone
 *     surrogate anywhere in the input raises `UnicodeEncodeError` with a
 *     position measured against the finished JSON text
 */

import { PyBytes } from './pybytes.mjs';
import { encodeJsonValue, encodeJsonString } from './jsonencoder.mjs';
import { encodeUtf8Strict } from './pyunicode.mjs';
import { compareCodePoints } from './pysort.mjs';

/** `canonicaljson.encode_canonical_json(obj) -> bytes` */
export function encodeCanonicalJson(obj) {
  return new PyBytes(encodeUtf8Strict(encodeJsonValue(obj)));
}

/**
 * `canonicaljson.encode_pretty_printed_json(obj) -> bytes`
 *
 * Provided for parity with the package's surface; `test7.py` does not use it.
 * The pretty encoder keeps `sort_keys=True` and `ensure_ascii=False` but adds
 * `indent=4`, which also switches the separators to `(',', ': ')`.
 */
export function encodePrettyPrintedJson(obj) {
  return new PyBytes(encodeUtf8Strict(prettyEncode(obj, 0)));
}

function isMapping(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function prettyEncode(value, depth) {
  const pad = ' '.repeat(4 * (depth + 1));
  const closePad = ' '.repeat(4 * depth);

  if (Array.isArray(value)) {
    if (value.length === 0) return '[]';
    const items = value.map((item) => pad + prettyEncode(item, depth + 1));
    return '[\n' + items.join(',\n') + '\n' + closePad + ']';
  }

  if (isMapping(value) && !(value instanceof PyBytes)) {
    const entries = value instanceof Map ? Array.from(value.entries()) : Object.entries(value);
    if (entries.length === 0) return '{}';
    const items = entries
      .map(([key, item]) => [String(key), item])
      .sort((left, right) => compareCodePoints(left[0], right[0]))
      .map(([key, item]) => `${pad}${encodeJsonString(key)}: ${prettyEncode(item, depth + 1)}`);
    return '{\n' + items.join(',\n') + '\n' + closePad + '}';
  }

  // Scalars share the canonical encoder's number formatting and escape table.
  return encodeJsonValue(value);
}

export { PyBytes };
=====JSONENCODER
/**
 * jsonencoder.mjs — a hand-written port of `json.JSONEncoder`'s serialisation,
 * configured the way canonicaljson configures it:
 *
 *     json.JSONEncoder(
 *         ensure_ascii=False,      # non-ASCII stays raw, no \uXXXX escapes
 *         allow_nan=False,         # NaN/Infinity raise ValueError
 *         separators=(',', ':'),   # no whitespace anywhere
 *         sort_keys=True,          # object keys in code point order
 *     )
 *
 * The result is a Python `str`; the UTF-8 encoding step happens afterwards in
 * `canonicaljson.mjs`. Keeping the two stages separate is what makes the
 * surrogate error positions line up with the reference implementation, because
 * CPython reports them as offsets into the finished JSON *text*.
 *
 * Everything here is bespoke: no host JSON serialiser is consulted, since the
 * escape table, key ordering and number formatting all have to follow CPython
 * rather than ECMAScript.
 */

import { PyTypeError, PyValueError } from './pyerrors.mjs';
import { compareCodePoints } from './pysort.mjs';
import { PyFloat, jsonNumberRepr } from './pynumber.mjs';

/**
 * `json.encoder.ESCAPE_DCT`, restricted to the entries that fire when
 * `ensure_ascii=False`. Note `/` is *not* escaped and neither is U+007F.
 */
const ESCAPE_TABLE = new Map([
  [0x5c, '\\\\'], // backslash
  [0x22, '\\"'], // double quote
  [0x08, '\\b'],
  [0x0c, '\\f'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
  [0x09, '\\t'],
]);

/**
 * `py_encode_basestring` — quote a string, escaping only what JSON requires.
 *
 * Iterating UTF-16 units rather than code points is deliberate and safe: every
 * escaped character is ASCII, so astral characters and lone surrogates are
 * copied through untouched either way, and surrogates must survive to this
 * point so that the later UTF-8 encode can reject them.
 */
export function encodeJsonString(value) {
  let out = '"';
  for (let i = 0; i < value.length; i += 1) {
    const unit = value.charCodeAt(i);
    const escape = ESCAPE_TABLE.get(unit);
    if (escape !== undefined) {
      out += escape;
    } else if (unit < 0x20) {
      out += '\\u' + unit.toString(16).padStart(4, '0');
    } else {
      out += value[i];
    }
  }
  return out + '"';
}

/**
 * Normalises a mapping into `[key, value]` pairs. `Map` is supported so callers
 * can use non-string keys the way a Python `dict` would, and plain objects are
 * treated as string-keyed dicts over their own enumerable properties.
 */
function mappingEntries(value) {
  if (value instanceof Map) return Array.from(value.entries());
  return Object.keys(value).map((key) => [key, value[key]]);
}

/**
 * `json` coerces non-string keys before writing them: `True`/`False`/`None`
 * become their Python literals, numbers use their repr, and anything else is a
 * TypeError.
 */
function coerceKey(key) {
  if (typeof key === 'string') return key;
  if (key === true) return 'true';
  if (key === false) return 'false';
  if (key === null) return 'null';
  if (typeof key === 'number' || typeof key === 'bigint' || key instanceof PyFloat) {
    return jsonNumberRepr(key);
  }
  throw new PyTypeError(`keys must be str, int, float, bool or None, not ${typeName(key)}`);
}

function typeName(value) {
  if (value === null) return 'NoneType';
  if (Array.isArray(value)) return 'list';
  if (value instanceof Map) return 'dict';
  if (value instanceof PyFloat) return 'float';
  switch (typeof value) {
    case 'string':
      return 'str';
    case 'boolean':
      return 'bool';
    case 'bigint':
      return 'int';
    case 'number':
      return Number.isInteger(value) ? 'int' : 'float';
    case 'undefined':
      return 'undefined';
    default:
      return 'object';
  }
}

/**
 * Serialise `value` to a canonical JSON *string*.
 *
 * `seen` reproduces `json`'s circular-reference guard, which raises
 * `ValueError: Circular reference detected`.
 */
export function encodeJsonValue(value, seen = new Set()) {
  if (value === null || value === undefined) return 'null';
  if (value === true) return 'true';
  if (value === false) return 'false';
  if (typeof value === 'string') return encodeJsonString(value);
  if (typeof value === 'number' || typeof value === 'bigint' || value instanceof PyFloat) {
    return jsonNumberRepr(value);
  }

  if (Array.isArray(value)) {
    if (seen.has(value)) throw new PyValueError('Circular reference detected');
    seen.add(value);
    const parts = value.map((item) => encodeJsonValue(item, seen));
    seen.delete(value);
    return '[' + parts.join(',') + ']';
  }

  if (typeof value === 'object') {
    if (seen.has(value)) throw new PyValueError('Circular reference detected');
    seen.add(value);
    // sort_keys=True sorts the coerced keys in code point order.
    const parts = mappingEntries(value)
      .map(([key, item]) => [coerceKey(key), item])
      .sort((left, right) => compareCodePoints(left[0], right[0]))
      .map(([key, item]) => encodeJsonString(key) + ':' + encodeJsonValue(item, seen));
    seen.delete(value);
    return '{' + parts.join(',') + '}';
  }

  throw new PyTypeError(`Object of type ${typeName(value)} is not JSON serializable`);
}

/**
 * pyunicode.mjs — the `str` <-> `bytes` boundary, with CPython's exact semantics.
 *
 * Two conversions matter for this program:
 *
 *   1. `os.fsdecode` / `sys.argv` decoding: UTF-8 with `errors='surrogateescape'`.
 *      Every byte CPython's UTF-8 decoder rejects becomes U+DC00+byte, i.e. a
 *      lone *low* surrogate in U+DC80..U+DCFF.
 *
 *   2. `str.encode('utf-8')` with `errors='strict'`, which is what canonicaljson
 *      performs last. Any surrogate code point raises `UnicodeEncodeError`, and
 *      CPython groups *consecutive* surrogates into one error range.
 *
 * Representation note: a Python `str` is modelled as a JS string. JS strings are
 * UTF-16, so in principle a high surrogate followed by a low surrogate would be
 * read back as one astral code point rather than two Python surrogates. That
 * ambiguity cannot arise here: `surrogateescape` only ever emits *low*
 * surrogates (U+DC80..U+DCFF), and a well-formed pair requires a *high*
 * surrogate first, so escaped bytes never coalesce.
 */

import { UnicodeEncodeError } from './pyerrors.mjs';

const SURROGATE_LOW = 0xd800;
const SURROGATE_HIGH = 0xdfff;

export function isSurrogate(cp) {
  return cp >= SURROGATE_LOW && cp <= SURROGATE_HIGH;
}

/** `len(s)` — Python counts code points, JS's `.length` counts UTF-16 units. */
export function pyLen(str) {
  let n = 0;
  for (const _ of str) n += 1;
  return n;
}

/** `[ord(c) for c in s]` */
export function codePoints(str) {
  const out = [];
  for (const ch of str) out.push(ch.codePointAt(0));
  return out;
}

/**
 * How many bytes a code point occupies in UTF-8, mirroring the table CPython
 * uses. Surrogates are handled by the caller (they are an error).
 */
function utf8Width(cp) {
  if (cp < 0x80) return 1;
  if (cp < 0x800) return 2;
  if (cp < 0x10000) return 3;
  return 4;
}

/**
 * `s.encode('utf-8')` with `errors='strict'`.
 *
 * Returns a `Uint8Array`. Raises `UnicodeEncodeError` on the first run of
 * surrogate code points, reporting the run's start/end as code point indices —
 * exactly what CPython's `_PyUnicode_EncodeUTF8` does when it walks forward
 * while `Py_UNICODE_IS_SURROGATE` holds.
 */
export function encodeUtf8Strict(str) {
  const out = [];
  let cpIndex = 0;
  let u = 0;

  while (u < str.length) {
    const cp = str.codePointAt(u);

    if (isSurrogate(cp)) {
      // Collect the maximal run of consecutive surrogates for the error range.
      let end = cpIndex + 1;
      let scan = u + 1; // a lone surrogate always occupies one UTF-16 unit
      while (scan < str.length && isSurrogate(str.codePointAt(scan))) {
        end += 1;
        scan += 1;
      }
      throw new UnicodeEncodeError('utf-8', str, cpIndex, end, 'surrogates not allowed');
    }

    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }

    u += utf8Width(cp) === 4 ? 2 : 1;
    cpIndex += 1;
  }

  return Uint8Array.from(out);
}

/**
 * The continuation-byte range CPython accepts for a given lead byte. Encoding
 * these bounds (rather than a blanket 0x80..0xBF) is what rejects overlong
 * forms, UTF-8-encoded surrogates (0xED 0xA0..) and code points above U+10FFFF.
 */
function secondByteRange(lead) {
  if (lead === 0xe0) return [0xa0, 0xbf];
  if (lead === 0xed) return [0x80, 0x9f];
  if (lead === 0xf0) return [0x90, 0xbf];
  if (lead === 0xf4) return [0x80, 0x8f];
  return [0x80, 0xbf];
}

/** Total UTF-8 sequence length for a lead byte, or 0 if it cannot start one. */
function sequenceLength(lead) {
  if (lead < 0x80) return 1;
  if (lead >= 0xc2 && lead <= 0xdf) return 2; // 0xc0/0xc1 are always overlong
  if (lead >= 0xe0 && lead <= 0xef) return 3;
  if (lead >= 0xf0 && lead <= 0xf4) return 4;
  return 0;
}

/**
 * `bytes.decode('utf-8', errors='surrogateescape')`.
 *
 * On an invalid sequence CPython reports the *maximal subpart* (the lead byte
 * plus any continuation bytes that were still valid) and the surrogateescape
 * handler replaces each of those bytes individually with U+DC00+byte. So
 * b'\xff\xfe' becomes '\udcff\udcfe' — two code points, which is why the
 * executable reports "position 2-3" rather than "position 2".
 */
export function decodeSurrogateEscape(bytes) {
  const buf = bytes instanceof Uint8Array ? bytes : Uint8Array.from(bytes);
  let out = '';
  let i = 0;

  const escapeRange = (from, to) => {
    for (let k = from; k < to; k += 1) out += String.fromCharCode(0xdc00 + buf[k]);
  };

  while (i < buf.length) {
    const lead = buf[i];

    if (lead < 0x80) {
      out += String.fromCharCode(lead);
      i += 1;
      continue;
    }

    const len = sequenceLength(lead);
    if (len === 0) {
      escapeRange(i, i + 1);
      i += 1;
      continue;
    }

    // Validate continuation bytes, tracking how many were acceptable so the
    // maximal subpart matches CPython's.
    let valid = 1;
    let ok = true;
    for (let k = 1; k < len; k += 1) {
      const pos = i + k;
      if (pos >= buf.length) {
        ok = false;
        break;
      }
      const b = buf[pos];
      const [lo, hi] = k === 1 ? secondByteRange(lead) : [0x80, 0xbf];
      if (b < lo || b > hi) {
        ok = false;
        break;
      }
      valid += 1;
    }

    if (!ok) {
      escapeRange(i, i + valid);
      i += valid;
      continue;
    }

    let cp;
    if (len === 2) {
      cp = ((lead & 0x1f) << 6) | (buf[i + 1] & 0x3f);
    } else if (len === 3) {
      cp = ((lead & 0x0f) << 12) | ((buf[i + 1] & 0x3f) << 6) | (buf[i + 2] & 0x3f);
    } else {
      cp =
        ((lead & 0x07) << 18) |
        ((buf[i + 1] & 0x3f) << 12) |
