 * `print` renders each argument with `str()`, which for `bytes` is its `repr()`
 * — that is exactly what `print(result1)` relies on in the Python source.
 */
export function pyPrint(...values) {
  const rendered = values.map((value) => (typeof value === 'string' ? value : pyRepr(value)));
  writeStdout(rendered.join(' ') + '\n');
}

/**
 * pyerrors.mjs — Python exception shapes reproduced in JavaScript.
