=====PYRUNTIME
/**
 * pyruntime.mjs — the top-level behaviour CPython supplies around `main()`.
 *
 * Three exit paths have to be reproduced:
 *
 *   * `SystemExit`  -> exit with its code, nothing extra on stderr
 *   * any other exception -> traceback on stderr, exit 1
 *   * clean return -> exit 0
 *
 * The reference program is a PyInstaller bundle, so an unhandled exception is
 * followed by PyInstaller's own `[PYI-<pid>:ERROR]` line. Both are emitted here
 * so stderr matches as closely as a non-Python process can manage.
 */

import { SystemExit, PyError } from './pyerrors.mjs';
import { writeStderr } from './pyio.mjs';

/**
 * Renders a CPython traceback from a static frame list, innermost last.
 * Each frame is `{ file, line, name }`.
 */
export function formatTraceback(frames, error) {
  let out = 'Traceback (most recent call last):\n';
  for (const frame of frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
  }
  const name = error instanceof PyError ? error.pyName : error.name || 'Exception';
  const message = error instanceof PyError ? error.toPyString() : error.message;
  out += message ? `${name}: ${message}\n` : `${name}\n`;
  return out;
}

/**
 * Runs `main` under CPython's exit semantics.
 *
 * `options.traceback` supplies the frame list for an unhandled exception, and
 * `options.script` is the module name PyInstaller reports.
 */
export function runMain(main, options = {}) {
  const frames = options.traceback || [];
  const script = options.script || 'test7';

  try {
    main();
  } catch (err) {
    if (err instanceof SystemExit) {
      process.exitCode = typeof err.code === 'number' ? err.code : err.code ? 1 : 0;
      return;
    }
    writeStderr(formatTraceback(frames, err));
    writeStderr(`[PYI-${process.pid}:ERROR] Failed to execute script '${script}' due to unhandled exception!\n`);
    process.exitCode = 1;
  }
}
