  formatOptionsSection(actions) {
    const invocations = actions.map((action) => HelpFormatter.invocation(action));
    const actionMaxLength = Math.max(0, ...invocations.map((text) => text.length)) + this.indentIncrement;
    const helpPosition = Math.min(actionMaxLength + 2, this.maxHelpPosition);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - this.indentIncrement - 2;

    let out = 'options:\n';
    actions.forEach((action, index) => {
      const header = invocations[index];
      if (!action.help) {
        out += ' '.repeat(this.indentIncrement) + header + '\n';
