  printHelp() {
    writeStdout(this.formatHelp());
  }

  /** `parser.error(message)` — usage on stderr, then `sys.exit(2)`. */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * `_parse_optional`. Returns `null` when the string is a positional, or
   * `[action, optionString, sep, explicitArg]` where `action` is `null` for an
   * option-looking string that matches nothing.
   *
   * `sep` records *how* an explicit argument was attached: `'='` when it was
   * split off an `=`, `''` when it was concatenated onto a single-dash option
   * (`-hx`), and `null` when there is none. The distinction is load-bearing —
   * `-hx` chains into another short option while `-h=x` is an error.
   */
  parseOptional(argString) {
    if (argString === '') return null;
    if (!this.prefixChars.includes(argString[0])) return null;

    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null, null];
    }
    if (argString.length === 1) return null; // a bare "-" is a positional

    const equalsAt = argString.indexOf('=');
    if (equalsAt !== -1) {
      const optionString = argString.slice(0, equalsAt);
      const explicitArg = argString.slice(equalsAt + 1);
      if (this.optionStringActions.has(optionString)) {
        return [this.optionStringActions.get(optionString), optionString, '=', explicitArg];
      }
    }

    const tuples = this.getOptionTuples(argString);
    if (tuples.length > 1) {
      const matches = tuples.map(([, optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (tuples.length === 1) {
      return tuples[0];
    }

    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals) return null;
    if (argString.includes(' ')) return null;

    return [null, argString, null, null];
  }

  /** `_get_option_tuples` — prefix matching for long and short options. */
  getOptionTuples(optionString) {
    const chars = this.prefixChars;
    const result = [];

    // A double-dash option is only ever split at an '='.
    if (chars.includes(optionString[0]) && chars.includes(optionString[1])) {
      if (!this.allowAbbrev) return result;
      const equalsAt = optionString.indexOf('=');
      const prefix = equalsAt !== -1 ? optionString.slice(0, equalsAt) : optionString;
      const sep = equalsAt !== -1 ? '=' : null;
      const explicitArg = equalsAt !== -1 ? optionString.slice(equalsAt + 1) : null;
      for (const [candidate, action] of this.optionStringActions) {
        if (candidate.startsWith(prefix)) result.push([action, candidate, sep, explicitArg]);
      }
      return result;
    }

    // A single-dash option may have its argument concatenated onto it.
    const shortPrefix = optionString.slice(0, 2);
    const shortExplicitArg = optionString.slice(2);
    for (const [candidate, action] of this.optionStringActions) {
      if (candidate === shortPrefix) {
        result.push([action, candidate, '', shortExplicitArg]);
      } else if (candidate.startsWith(optionString)) {
        result.push([action, candidate, null, null]);
      }
    }
    return result;
  }

  /**
   * `_match_argument` for `nargs=None`. For optionals argparse strips `-` from
   * the nargs pattern, leaving `(A)`: the very next slot must be a plain value,
   * so a following option string or `--` is a hard error.
   */
  matchArgument(action, pattern) {
    if (action.nargs === 0) return 0;
    if (pattern.length >= 1 && pattern[0] === 'A') return 1;
    throw new ArgumentError(action, 'expected one argument');
  }

  /** `parse_args` */
  parseArgs(args) {
    const [namespace, extras] = this.parseKnownArgs(args);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /** `parse_known_args` / `_parse_known_args` */
  parseKnownArgs(argStrings) {
    const args = Array.from(argStrings);
    const namespace = new Namespace();
    for (const action of this.actions) {
      if (action.action === 'store') namespace[action.dest] = action.defaultValue;
    }

    // Classify each argument: 'O' option, 'A' value, '-' the "--" separator.
    const pattern = [];
    const optionIndices = new Map();
    let sawSeparator = false;
    for (let i = 0; i < args.length; i += 1) {
      if (sawSeparator) {
        pattern.push('A');
        continue;
      }
      if (args[i] === '--') {
        pattern.push('-');
        sawSeparator = true;
        continue;
      }
      const optionTuple = this.parseOptional(args[i]);
      if (optionTuple === null) {
        pattern.push('A');
      } else {
        optionIndices.set(i, optionTuple);
        pattern.push('O');
      }
    }

    const seenActions = new Set();
    const extras = [];

    const takeAction = (action, values) => {
      seenActions.add(action);
      if (action.action === 'help') {
        this.printHelp();
        throw new SystemExit(0);
      }
      // type=str is the identity conversion.
      namespace[action.dest] = action.nargs === 0 ? true : values[0];
    };

    /**
     * `consume_optional`. Actions are collected into `actionTuples` and only
     * applied once the loop settles, so an error raised part-way through a
     * concatenated short-option chain applies nothing at all.
     */
    const consumeOptional = (startIndex) => {
      let [action, optionString, sep, explicitArg] = optionIndices.get(startIndex);
      const actionTuples = [];
      let stop;

      for (;;) {
        if (action === null) {
          extras.push(args[startIndex]);
          return startIndex + 1;
        }

        if (explicitArg !== null) {
          const argCount = this.matchArgument(action, ['A']);
          const chars = this.prefixChars;

          if (argCount === 0 && !chars.includes(optionString[1]) && explicitArg !== '') {
            // A single-dash flag with something glued to it: try to read the
            // tail as further short options, as in `-hx` -> `-h` then `-x`.
            // An explicit `=` or a dash-prefixed tail is a hard error instead.
            if (sep || chars.includes(explicitArg[0])) {
              throw new ArgumentError(action, `ignored explicit argument '${explicitArg}'`);
            }
            actionTuples.push([action, [], optionString]);
            const char = optionString[0];
            optionString = char + explicitArg[0];
            if (this.optionStringActions.has(optionString)) {
              action = this.optionStringActions.get(optionString);
              explicitArg = explicitArg.slice(1);
              if (explicitArg === '') {
                sep = null;
                explicitArg = null;
              } else if (explicitArg[0] === '=') {
                sep = '=';
                explicitArg = explicitArg.slice(1);
              } else {
                sep = '';
              }
              continue;
            }
            extras.push(char + explicitArg);
            stop = startIndex + 1;
            break;
          }

          if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          }

          throw new ArgumentError(action, `ignored explicit argument '${explicitArg}'`);
        }

        const start = startIndex + 1;
        const argCount = this.matchArgument(action, pattern.slice(start));
        stop = start + argCount;
        actionTuples.push([action, args.slice(start, stop)]);
        break;
      }

      for (const [tupleAction, values] of actionTuples) takeAction(tupleAction, values);
      return stop;
    };

    const optionKeys = Array.from(optionIndices.keys());
    const maxOptionIndex = optionKeys.length > 0 ? Math.max(...optionKeys) : -1;

    let startIndex = 0;
    try {
      while (startIndex <= maxOptionIndex) {
        const nextOptionIndex = Math.min(...optionKeys.filter((index) => index >= startIndex));
        // No positionals are declared, so anything before the next option is
        // unparseable and goes straight to extras.
        if (startIndex !== nextOptionIndex) {
          extras.push(...args.slice(startIndex, nextOptionIndex));
          startIndex = nextOptionIndex;
        }
        startIndex = consumeOptional(nextOptionIndex);
      }
    } catch (err) {
      if (err instanceof ArgumentError) this.error(err.message);
      throw err;
    }

    extras.push(...args.slice(startIndex));

    const missing = this.actions
      .filter((action) => action.required && !seenActions.has(action))
      .map((action) => action.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }
}

