/**
 * par.mjs — parallel front-end for the differential harness.
 *
 * Reproduces harness.mjs's argv delivery and comparison rules exactly (same
 * bash $'\xNN' quoting, same [PYI-<pid>:ERROR] masking) but runs N cases at a
 * time so exhaustive sweeps finish in minutes rather than hours. Any case that
 * looks like a failure is re-checked through the real harness `checkCase`
 * before it is reported, so the harness stays authoritative.
 */
import { spawn } from 'node:child_process';
import { checkCase, toBuf } from './harness.mjs';

const PY = '/workspace/dataset/test7_executable';
const JS = '/output/test7.mjs';
const CONCURRENCY = Number(process.env.DH_JOBS || 32);

function bashQuote(buf) {
  let out = "$'";
  for (const b of buf) {
    if (b === 0) throw new Error('NUL cannot appear in argv');
    out += '\\x' + b.toString(16).padStart(2, '0');
  }
  return out + "'";
}

function run(cmd) {
  return new Promise((resolve) => {
    const child = spawn('/bin/bash', ['-c', cmd], { stdio: ['ignore', 'pipe', 'pipe'] });
    const out = [];
    const err = [];
    child.stdout.on('data', (d) => out.push(d));
    child.stderr.on('data', (d) => err.push(d));
    child.on('close', (code) =>
      resolve({ out: Buffer.concat(out), err: Buffer.concat(err), code }),
    );
  });
}

const mask = (b) => b.toString('utf8').replace(/\[PYI-\d+:ERROR\]/g, '[PYI:ERROR]');

async function oneCase(argv) {
  const quoted = argv.map((a) => bashQuote(toBuf(a))).join(' ');
  const [py, js] = await Promise.all([run(`${PY} ${quoted}`), run(`node ${JS} ${quoted}`)]);
  const problems = [];
  if (!py.out.equals(js.out)) {
    problems.push(
      `stdout differs\n  py: ${py.out.toString('latin1')}\n  js: ${js.out.toString('latin1')}`,
    );
  }
  if (py.code !== js.code) problems.push(`exit code differs: py=${py.code} js=${js.code}`);
  if (mask(py.err) !== mask(js.err)) {
    problems.push(`stderr differs\n  py: ${mask(py.err)}\n  js: ${mask(js.err)}`);
  }
  return problems;
}

/**
 * Run `cases` in parallel. Returns { total, failures: [{label, argv, problems}] }.
 * Failures are confirmed by re-running through harness.checkCase.
 */
export async function runSuitePar(name, cases, opts = {}) {
  const limit = opts.jobs || CONCURRENCY;
  const maxReport = opts.maxReport === undefined ? 12 : opts.maxReport;
  const failures = [];
  let next = 0;
  let reported = 0;

  const norm = (entry) =>
    Array.isArray(entry)
      ? { argv: entry, label: entry.map((a) => toBuf(a).toString('latin1')).join(' | ') }
      : { argv: entry.argv, label: entry.label || entry.argv.map((a) => toBuf(a).toString('latin1')).join(' | ') };

  async function worker() {
    for (;;) {
      const i = next++;
      if (i >= cases.length) return;
      const { argv, label } = norm(cases[i]);
      const problems = await oneCase(argv);
      if (problems.length > 0) {
        // Confirm through the canonical (synchronous) harness.
        const confirmed = checkCase(argv);
        if (confirmed.length === 0) continue; // flake, not a divergence
        failures.push({ label, argv, problems: confirmed });
        if (reported < maxReport) {
          reported += 1;
          process.stdout.write(`FAIL [${name}] ${label}\n`);
          for (const p of confirmed) process.stdout.write('  ' + p.replace(/\n/g, '\n  ') + '\n');
        }
      }
    }
  }

  await Promise.all(Array.from({ length: Math.min(limit, cases.length) }, worker));
  process.stdout.write(
    `[${name}] ${cases.length - failures.length}/${cases.length} passed` +
      (failures.length > maxReport ? ` (${failures.length - maxReport} further failures suppressed)` : '') +
      '\n',
  );
  return { total: cases.length, failures };
}

/**
 * unicode-planes.mjs — exhaustive Unicode sweep of the test7 port.
 *
 * Campaign: encoding AND sort-order divergence across the whole Unicode space.
 *
 *   node /tmp/dh/unicode-planes.mjs            # every suite
 *   node /tmp/dh/unicode-planes.mjs ascii order  # only the named suites
 *
 * Every case goes through the byte-exact differential harness (par.mjs is a
 * parallel front-end that re-confirms each failure with harness.checkCase).
 */
import { runSuitePar } from './par.mjs';
import { checkCase } from './harness.mjs';

const cp = (n) => String.fromCodePoint(n);
const isSurr = (n) => n >= 0xd800 && n <= 0xdfff;

/* ------------------------------------------------------------------ helpers */

/** All code points, in order, skipping NUL (illegal in argv) and surrogates. */
function* allCodePoints() {
  for (let n = 1; n <= 0x10ffff; n += 1) if (!isSurr(n)) yield n;
}

function chunk(iter, size) {
  const out = [];
  let cur = [];
  for (const v of iter) {
    cur.push(v);
    if (cur.length === size) {
      out.push(cur);
      cur = [];
    }
  }
  if (cur.length) out.push(cur);
  return out;
}

/** Bisect a failing multi-code-point case down to a single code point. */
async function bisect(points, build) {
  let list = points;
  while (list.length > 1) {
    const mid = Math.floor(list.length / 2);
    const left = list.slice(0, mid);
    const right = list.slice(mid);
    if (checkCase(build(left)).length > 0) list = left;
    else if (checkCase(build(right)).length > 0) list = right;
    else break; // interaction between the halves
  }
  return list;
}

/* ------------------------------------------------------------------- suites */

/** Every ASCII byte, alone and paired, in both argument slots and both orders. */
function suiteAscii() {
  const cases = [];
  for (let n = 1; n <= 0x7f; n += 1) {
    const c = cp(n);
    cases.push(['--a', c, '--b', 'M']);
    cases.push(['--a', 'M', '--b', c]);
    cases.push(['--a', c, '--b', c]);
    cases.push(['--a', 'x' + c + 'y', '--b', 'x']);
    // ordering against both ends of the ASCII range
    cases.push(['--a', c, '--b', '']);
    cases.push(['--a', '', '--b', c]);
  }
  // whole ASCII range in one string, and reversed
  const ascii = Array.from({ length: 0x7f }, (_, i) => cp(i + 1)).join('');
  cases.push(['--a', ascii, '--b', Array.from(ascii).reverse().join('')]);
  cases.push(['--a', ascii, '--b', ascii]);
  return cases;
}

/** UTF-8 width boundaries and the code points immediately around them. */
function suiteBoundary() {
  const marks = [
    0x01, 0x7e, 0x7f, 0x80, 0x81, 0x7fe, 0x7ff, 0x800, 0x801, 0xd7fe, 0xd7ff, 0xe000, 0xe001,
    0xfffd, 0xfffe, 0xffff, 0x10000, 0x10001, 0x1fffe, 0x1ffff, 0x20000, 0x3ffff, 0x40000,
    0xfffff, 0x100000, 0x10fffe, 0x10ffff, 0x2ff, 0x300, 0x7f0, 0xffef,
  ];
  const cases = [];
  for (const n of marks) {
    const c = cp(n);
    cases.push(['--a', c, '--b', 'M']);
    cases.push(['--a', 'M', '--b', c]);
    cases.push(['--a', c, '--b', c]);
    cases.push(['--a', c + c, '--b', c]);
    for (const m of marks) {
      const d = cp(m);
      cases.push(['--a', c, '--b', d]);
    }
  }
  return cases;
}

/**
 * Exhaustive encoding sweep: every code point U+0001..U+10FFFF (minus
 * surrogates) appears in some argument. Two passes with different chunk
 * alignments so no bug can hide on a chunk boundary.
 */
function suiteSweep(size, offset) {
  const points = Array.from(allCodePoints());
  const shifted = offset ? points.slice(offset).concat(points.slice(0, offset)) : points;
  const chunks = chunk(shifted, size);
  const cases = [];
  for (let i = 0; i < chunks.length; i += 2) {
    const a = chunks[i].map(cp).join('');
    const b = (chunks[i + 1] || chunks[i]).map(cp).join('');
    cases.push({
      argv: ['--a', a, '--b', b],
      label: `sweep U+${chunks[i][0].toString(16)}..U+${(chunks[i + 1] || chunks[i]).slice(-1)[0].toString(16)}`,
      points: chunks[i].concat(chunks[i + 1] || []),
    });
  }
  return cases;
}

/**
 * The exact band where JS '<' disagrees with Python: an astral character's
 * first UTF-16 unit is D800..DBFF, which ranks *below* every BMP character in
 * U+E000..U+FFFF, while its code point ranks above. Full sweep of the band,
 * both argument orders.
 */
function suiteSurrogateOrder(astral, stride) {
  const cases = [];
  const A = cp(astral);
  for (let n = 0xe000; n <= 0xffff; n += stride) {
    const B = cp(n);
    cases.push({ argv: ['--a', A, '--b', B], label: `U+${astral.toString(16)} vs U+${n.toString(16)}` });
    cases.push({ argv: ['--a', B, '--b', A], label: `U+${n.toString(16)} vs U+${astral.toString(16)}` });
  }
  return cases;
}

/** Many astral characters against sampled BMP-high, plus astral vs astral. */
function suiteAstralOrder() {
  const astrals = [
    0x10000, 0x10001, 0x1000f, 0x103a0, 0x10fff, 0x11000, 0x1d11e, 0x1d7ce, 0x1f300, 0x1f600,
    0x1f9d1, 0x20000, 0x2070e, 0x2a6d6, 0x2ffff, 0x30000, 0x3fffd, 0x40000, 0x4ffff, 0x50000,
    0x5ffff, 0x60000, 0x6ffff, 0x70000, 0x7ffff, 0x80000, 0x8ffff, 0x90000, 0x9ffff, 0xa0000,
    0xaffff, 0xb0000, 0xbffff, 0xc0000, 0xcffff, 0xd0000, 0xdffff, 0xe0000, 0xe0100, 0xeffff,
    0xf0000, 0xfffff, 0x100000, 0x10fffd, 0x10fffe, 0x10ffff,
  ];
  const bmpHigh = [];
  for (let n = 0xe000; n <= 0xffff; n += 137) bmpHigh.push(n);
  bmpHigh.push(0xe000, 0xdfff + 1, 0xf8ff, 0xfb00, 0xfdd0, 0xfdef, 0xfeff, 0xfff9, 0xfffd, 0xfffe, 0xffff);
  const lowBmp = [0x01, 0x41, 0x7f, 0x80, 0x7ff, 0x800, 0x2028, 0x2029, 0x3042, 0xd7ff];

  const cases = [];
  for (const A of astrals) {
    for (const B of bmpHigh.concat(lowBmp)) {
      cases.push({ argv: ['--a', cp(A), '--b', cp(B)], label: `U+${A.toString(16)} / U+${B.toString(16)}` });
      cases.push({ argv: ['--a', cp(B), '--b', cp(A)], label: `U+${B.toString(16)} / U+${A.toString(16)}` });
    }
  }
  // astral vs astral, both orders
  for (const A of astrals) {
    for (const B of astrals) {
      cases.push({ argv: ['--a', cp(A), '--b', cp(B)], label: `astral U+${A.toString(16)} / U+${B.toString(16)}` });
    }
  }
  return cases;
}

/**
 * Ordering when the divergent character is not first: shared prefixes, one
 * string a proper prefix of the other, and mixed BMP/astral tails. Prefixes are
 * chosen so that UTF-16 unit counts and code point counts disagree.
 */
function suitePrefixOrder() {
  const prefixes = ['', 'Z', cp(0x10000), cp(0xffff), cp(0x10000) + cp(0xffff), 'ab', cp(0x1f600)];
  const tails = ['', 'A', cp(0xe000), cp(0xffff), cp(0x10000), cp(0x10ffff), cp(0x7f), cp(0xd7ff)];
  const cases = [];
  for (const p of prefixes) {
    for (const t1 of tails) {
      for (const t2 of tails) {
        cases.push({ argv: ['--a', p + t1, '--b', p + t2], label: `prefix ${JSON.stringify(p)} ${JSON.stringify(t1)}/${JSON.stringify(t2)}` });
      }
    }
  }
  return cases;
}

/** Non-characters: U+FDD0..U+FDEF and U+xFFFE/U+xFFFF in every plane. */
function suiteNonCharacters() {
  const points = [];
  for (let n = 0xfdd0; n <= 0xfdef; n += 1) points.push(n);
  for (let plane = 0; plane <= 0x10; plane += 1) {
    points.push(plane * 0x10000 + 0xfffe, plane * 0x10000 + 0xffff);
  }
  const cases = [];
  for (const n of points) {
    const c = cp(n);
    cases.push({ argv: ['--a', c, '--b', 'M'], label: `noncharacter U+${n.toString(16)} first` });
    cases.push({ argv: ['--a', 'M', '--b', c], label: `noncharacter U+${n.toString(16)} second` });
    cases.push({ argv: ['--a', c, '--b', c], label: `noncharacter U+${n.toString(16)} twice` });
    cases.push({ argv: ['--a', c, '--b', cp(0x10000)], label: `noncharacter U+${n.toString(16)} vs U+10000` });
    cases.push({ argv: ['--a', cp(0x10000), '--b', c], label: `U+10000 vs noncharacter U+${n.toString(16)}` });
  }
  cases.push({ argv: ['--a', points.map(cp).join(''), '--b', points.map(cp).reverse().join('')], label: 'all noncharacters' });
  return cases;
}

/** Scripts, combining marks, RTL, CJK, emoji, ZWJ, skin tones, BOM, LS/PS. */
function suiteSpecial() {
  const strings = [
    // combining marks / NFC vs NFD
    'é', 'é', 'à́̂', 'Å', 'Å', 'Å',
    'q̣̇', 'q̣̇', 'ḍ̇', 'ḍ̇',
    'ཷ', 'ཱྀ', 'ợ', 'ợ',
    // Hangul jamo vs precomposed
    '가', '가', '힣', '힣',
    // RTL
    'אבג', 'العربية',
    '‏א‎', '‮AB‬', '؜م',
    'أَلْف', 'שָלוֹם',
    // CJK
    '日本語', '中文', '한국어',
    '぀ぁゟ', '゠ヿ', '一鿿',
    cp(0x20000) + cp(0x2a6df), cp(0x2ceb0), cp(0x3134a),
    '﨎', '豈', '﫿', '⾀0',
    // emoji, ZWJ sequences, skin tone modifiers, flags, keycaps
    cp(0x1f600), cp(0x1f469) + '‍' + cp(0x1f4bb),
    cp(0x1f468) + '‍' + cp(0x1f469) + '‍' + cp(0x1f467) + '‍' + cp(0x1f466),
    cp(0x1f469) + cp(0x1f3fb), cp(0x1f469) + cp(0x1f3ff),
    cp(0x1f9d1) + cp(0x1f3fd) + '‍' + cp(0x1f91d) + '‍' + cp(0x1f9d1) + cp(0x1f3ff),
    cp(0x1f1fa) + cp(0x1f1f8), cp(0x1f1ef) + cp(0x1f1f5),
    '#️⃣', '1️⃣',
    cp(0x1f3f4) + cp(0xe0067) + cp(0xe0062) + cp(0xe0073) + cp(0xe0063) + cp(0xe0074) + cp(0xe007f),
    '☝️', '☝︎', cp(0x1f62e) + '‍' + cp(0x1f4a8),
    // BOM / line separators / other format controls
    '﻿', '﻿a', 'a﻿', '￾', ' ', ' ',
    'a b', 'a b', '', '', ' ', '',
    '​‌‍⁠', '­', '᠎', '　', ' ',
    // variation selectors + astral variation selectors
    'a︀', 'a' + cp(0xe0100), cp(0xe0101),
    // private use
    '', '', cp(0xf0000), cp(0xffffd), cp(0x100000), cp(0x10fffd),
    // Indic / Thai / Myanmar / Ethiopic / Cherokee / Deseret / Gothic / Linear B
    'क्ष', 'กำข', 'ကု', 'ሀ፼', 'Ꭰꭰ',
    cp(0x10400) + cp(0x10428), cp(0x10330), cp(0x10000) + cp(0x1000b),
    // math / musical / tags / ancient
    cp(0x1d400) + cp(0x1d7ff), cp(0x1d100) + cp(0x1d1e8), cp(0x12000) + cp(0x1236e),
    cp(0x1f0a0), cp(0x2f800), cp(0xe0001),
    // escape-sensitive mixes
    '"é"', '\\' + cp(0x1f600), '\t' + cp(0x10000) + '\n', '�'.length ? 'x' : 'x',
    '' + cp(0xffff), cp(0x10ffff) + '\\"',
    '', '/é/', "'" + cp(0x1f600) + "'",
  ];
  const partners = ['M', '', 'a', cp(0x10000), cp(0xffff), '﻿', cp(0x1f600), 'é', 'é'];
  const cases = [];
  for (const s of strings) {
    for (const p of partners) {
      cases.push({ argv: ['--a', s, '--b', p], label: `special ${JSON.stringify(s)} / ${JSON.stringify(p)}` });
      cases.push({ argv: ['--a', p, '--b', s], label: `special ${JSON.stringify(p)} / ${JSON.stringify(s)}` });
    }
    cases.push({ argv: ['--a', s, '--b', s], label: `special dup ${JSON.stringify(s)}` });
  }
  return cases;
}

/**
 * Every ASCII escape target crossed with a non-ASCII neighbour, in both
 * argument slots, so the escape table and the raw UTF-8 passthrough are
 * exercised together.
 */
function suiteEscapeMix() {
  const escapees = ['\\', '"', '\b', '\f', '\n', '\r', '\t', '', '', '', "'", '/', ''];
  const others = ['', '߿', 'ࠀ', '￿', cp(0x10000), cp(0x10ffff), '﻿', ' '];
  const cases = [];
  for (const e of escapees) {
    for (const o of others) {
      cases.push({ argv: ['--a', e + o, '--b', o + e], label: `mix ${JSON.stringify(e)} ${JSON.stringify(o)}` });
      cases.push({ argv: ['--a', o + e + o, '--b', e], label: `mix2 ${JSON.stringify(e)} ${JSON.stringify(o)}` });
    }
  }
  return cases;
}

/**
 * Unicode decimal digits (category Nd) after a leading '-'. CPython's
 * `re` treats `\d` as Nd-wide for str patterns, so argparse's
 * `_negative_number_matcher` accepts these as values; JS `\d` is ASCII-only.
 */
function ndCodePoints() {
  const out = [];
  const re = /^\p{Nd}$/u;
  for (const n of allCodePoints()) if (n > 0x7f && re.test(cp(n))) out.push(n);
  return out;
}

function suiteDigits(stride) {
  const nd = ndCodePoints();
  const cases = [];
  for (let i = 0; i < nd.length; i += stride) {
    const c = cp(nd[i]);
    cases.push({ argv: ['--a', '-' + c, '--b', 'x'], label: `neg U+${nd[i].toString(16)}` });
    cases.push({ argv: ['--a', 'x', '--b', '-' + c], label: `neg-b U+${nd[i].toString(16)}` });
    cases.push({ argv: ['--a', '-.' + c, '--b', 'x'], label: `negdot U+${nd[i].toString(16)}` });
    cases.push({ argv: ['--a', '-' + c + '5', '--b', 'x'], label: `negmix U+${nd[i].toString(16)}` });
    cases.push({ argv: ['--a', '-' + c + '.' + c, '--b', 'x'], label: `negfrac U+${nd[i].toString(16)}` });
  }
  // non-Nd numerics must stay errors in both
  for (const n of [0xb2, 0xb3, 0xb9, 0xbc, 0xbd, 0x2070, 0x2080, 0x2150, 0x2160, 0x3007, 0x4e00, 0x1369, 0x10107, 0x1d7ce - 1]) {
    cases.push({ argv: ['--a', '-' + cp(n), '--b', 'x'], label: `nonNd U+${n.toString(16)}` });
  }
  return cases;
}

/** Long strings across planes, to catch buffer/width mistakes. */
function suiteBulk() {
  const cases = [];
  const reps = [1, 2, 3, 7, 64, 500, 2000];
  for (const n of [0x41, 0x80, 0x7ff, 0x800, 0xffff, 0x10000, 0x10ffff, 0xe000, 0xfeff]) {
    for (const r of reps) {
      cases.push({ argv: ['--a', cp(n).repeat(r), '--b', cp(n).repeat(r + 1)], label: `bulk U+${n.toString(16)} x${r}` });
      cases.push({ argv: ['--a', cp(n).repeat(r + 1), '--b', cp(n).repeat(r)], label: `bulk-rev U+${n.toString(16)} x${r}` });
    }
  }
  // a value made of one code point from each plane, all 17 planes
  let mixed = '';
  for (let p = 0; p <= 0x10; p += 1) mixed += cp(p === 0 ? 0x41 : p * 0x10000 + 0x100);
  cases.push({ argv: ['--a', mixed, '--b', Array.from(mixed).reverse().join('')], label: 'one per plane' });
  return cases;
}

/* --------------------------------------------------------------------- main */

const SUITES = {
  ascii: () => suiteAscii(),
  boundary: () => suiteBoundary(),
  sweep: () => suiteSweep(1024, 0),
  sweep2: () => suiteSweep(701, 373),
  surr: () => suiteSurrogateOrder(0x10000, 1),
  surr2: () => suiteSurrogateOrder(0x10ffff, 3),
  astral: () => suiteAstralOrder(),
  prefix: () => suitePrefixOrder(),
  nonchar: () => suiteNonCharacters(),
  special: () => suiteSpecial(),
  escmix: () => suiteEscapeMix(),
  digits: () => suiteDigits(1),
  bulk: () => suiteBulk(),
};

const wanted = process.argv.slice(2).filter((a) => !a.startsWith('-'));
const names = wanted.length ? wanted : Object.keys(SUITES);

let total = 0;
const allFailures = [];
for (const name of names) {
  if (!SUITES[name]) {
    console.log(`unknown suite ${name}`);
    continue;
  }
  const cases = SUITES[name]();
  const t0 = Date.now();
  const { failures } = await runSuitePar(name, cases);
  total += cases.length;
  process.stdout.write(`   (${((Date.now() - t0) / 1000).toFixed(1)}s)\n`);
  for (const f of failures) allFailures.push({ suite: name, ...f });

  // For sweep suites, bisect the first few failures down to one code point.
  const withPoints = failures.filter((f) => cases.find((c) => c.label === f.label && c.points));
  for (const f of withPoints.slice(0, 4)) {
    const entry = cases.find((c) => c.label === f.label);
    const build = (pts) => ['--a', pts.map(cp).join(''), '--b', 'M'];
    const minimal = await bisect(entry.points, build);
    process.stdout.write(`   bisected ${f.label} -> ${minimal.map((n) => 'U+' + n.toString(16)).join(' ')}\n`);
  }
}

process.stdout.write(`\nTOTAL: ${total} cases, ${allFailures.length} divergent\n`);
if (allFailures.length) {
  const seen = new Set();
  for (const f of allFailures) {
    const key = f.suite;
    if (seen.has(key) && seen.size > 40) continue;
    seen.add(key);
  }
  process.stdout.write('divergent suites: ' + Array.from(new Set(allFailures.map((f) => f.suite))).join(', ') + '\n');
}
